// Array index constants for play types
const OFF_ORDER = ['is', 'tr', 'pb', 'pr', 'pu', 'su', 'hd', 'cu', 'os', 'or'];
const DEF_ORDER = ['is', 'pb', 'pr', 'pu', 'su', 'hd', 'os'];
const SUPP_ORDER = ['rf', 'rp', 'rm', 'pp', 'ppp'];
const OFF_KEY_MAP = {is:"Isolation",tr:"Transition",pb:"PRBallHandler",pr:"PRRollman",pu:"Postup",su:"Spotup",hd:"Handoff",cu:"Cut",os:"OffScreen",or:"OffRebound"};
const DEF_KEY_MAP = {is:"Isolation",pb:"PRBallHandler",pr:"PRRollman",pu:"Postup",su:"Spotup",hd:"Handoff",os:"OffScreen"};
const BOX_ORDER = ['ast_pct','fg3a_rate','usg_pct','oreb_pct'];
const ZONE_ORDER = ['RA','Paint','MR','C3','AB3'];
const ZONE_LABELS = {RA:'Restricted Area',Paint:'Paint',MR:'Mid-Range',C3:'Corner 3',AB3:'Above Break 3'};
const HUSTLE_ORDER = ['screen_ast_per36','screen_ast_pts_per36','contested_2pt_per36','contested_3pt_per36','deflections_per36'];
const TOUCH_ORDER = ['touches_per36','pass_pct','ast_pct','fg_pct'];
const TOUCH_TYPE_KEYS = { e: 'elbow', o: 'post', a: 'paint' };
const TOUCH_TYPE_LABELS = { elbow: 'Elbow', post: 'Post', paint: 'Paint' };
const DRIVE_ORDER = ['drives_per36','drive_pass_pct','drive_ast_pct','drive_tov_pct','drive_fg_pct'];

// Decode array-encoded player data back to objects
function decodePlayer(raw) {
  const result = {};
  for (const [season, d] of Object.entries(raw)) {
    const o = {}, de = {}, ro = {}, rd = {};
    OFF_ORDER.forEach((k,i) => { if(d.o[i]) o[k]=d.o[i]; if(d.ro[i]) ro[k]=d.ro[i]; });
    DEF_ORDER.forEach((k,i) => { if(d.d[i]) de[k]=d.d[i]; if(d.rd[i]) rd[k]=d.rd[i]; });
    const s = {};
    SUPP_ORDER.forEach((k,i) => { if(d.s[i]) s[k]=d.s[i]; });
    // Decode efficiency: {key: [ppp, fg]} -> {key: {pp, fg}}
    const eo = {}, ed = {};
    if(d.eo) Object.entries(d.eo).forEach(([k,v]) => { eo[OFF_KEY_MAP[k]||k] = {pp:v[0],fg:v[1]}; });
    if(d.ed) Object.entries(d.ed).forEach(([k,v]) => { ed[DEF_KEY_MAP[k]||k] = {pp:v[0],fg:v[1]}; });
    const bx = {};
    if(d.bx) BOX_ORDER.forEach((k,i) => { if(d.bx[i] != null) bx[k]=d.bx[i]; });
    // Decode shot zones: [[freq,fg_pct],...] -> {zone: {freq, fg_pct}}
    const szo = {}, szd = {};
    if(d.szo) d.szo.forEach((v,i) => { if(v) szo[ZONE_ORDER[i]]={freq:v[0],fg_pct:v[1]}; });
    if(d.szd) d.szd.forEach((v,i) => { if(v) szd[ZONE_ORDER[i]]={freq:v[0],fg_pct:v[1]}; });
    const hu = {};
    if (d.hu) HUSTLE_ORDER.forEach((k,i) => { if (d.hu[i] != null) hu[k] = d.hu[i]; });
    const tc = {};
    if (d.tc) for (const [short, arr] of Object.entries(d.tc)) {
      const type = TOUCH_TYPE_KEYS[short];
      if (!type) continue;
      const entry = {};
      TOUCH_ORDER.forEach((k,i) => { if (arr[i] != null) entry[k] = arr[i]; });
      tc[type] = entry;
    }
    const dr = {};
    if (d.dr) DRIVE_ORDER.forEach((k,i) => { if (d.dr[i] != null) dr[k] = d.dr[i]; });
    const mu = d.mu ? { fg_pct: d.mu[0], poss: d.mu[1] } : null;
    result[season] = { t:d.t, p:d.p, id:d.id, pt:d.pt, gwc:d.gwc, o, d:de, ro, rd, s,
      ...(Object.keys(eo).length && {eo}),
      ...(Object.keys(ed).length && {ed}),
      ...(Object.keys(bx).length && {bx}),
      ...(Object.keys(szo).length && {szo}),
      ...(Object.keys(szd).length && {szd}),
      ...(Object.keys(hu).length && {hu}),
      ...(Object.keys(tc).length && {tc}),
      ...(Object.keys(dr).length && {dr}),
      ...(mu && {mu}) };
  }
  return result;
}

// Build full NBA_DATA object
const NBA_DATA = Object.fromEntries(
  Object.entries(NBA_DATA_RAW).map(([name, seasons]) => [name, decodePlayer(seasons)])
);


// Compressed field accessors
const getTeam = d => d?.t || "";
const getPreviousTeam = d => d?.pt || null;
const getGamesWithCurrent = d => d?.gwc ?? null;
// Short, human label for a team transition. Free agency and mid-season trades share the
// same display idea — where a player is now, and where they were before that.
function teamLabel(d) {
  return teamLabelParts(getTeam(d), getPreviousTeam(d), getGamesWithCurrent(d));
}
// Same logic, for call sites that only have already-flattened team/previousTeam/gamesWithCurrent
// fields on a playerData/player object rather than the raw decoded player-season object.
function teamLabelParts(t, pt, g) {
  if (!pt) return t;
  if (t === "FA") return `FA · last with ${pt}`;
  return `${t} · traded from ${pt}${g != null ? ` (${g} GP)` : ""}`;
}
const getPos = d => d?.p || "";
const getId = d => d?.id || null;
const getSupp = d => d?.s ? { rim_freq: d.s.rf, rim_fg_pct_allowed: d.s.rp, rim_plusminus: d.s.rm, pr_poss_pct: d.s.pp, pr_ppp: d.s.ppp } : null;
// Efficiency already decoded with full key names in decodePlayer
const getEffOffExp = d => d?.eo || {};
const getEffDefExp = d => d?.ed || {};
const getBox = d => d?.bx || {};
const getShotZoneOff = d => d?.szo || {};
const getShotZoneDef = d => d?.szd || {};
const getHustle = d => d?.hu || {};
const getTouches = d => d?.tc || {};
const getDrive = d => d?.dr || {};
const getMatchup = d => d?.mu || null;


// Play type key maps (short -> full name)
const OFF_SHORT_MAP = Object.fromEntries(Object.entries(OFF_KEY_MAP).map(([k,v])=>[v,k]));
const DEF_SHORT_MAP = Object.fromEntries(Object.entries(DEF_KEY_MAP).map(([k,v])=>[v,k]));

// Expand compressed keys to full names for engine
const expandKeys = (obj, keyMap) => Object.fromEntries(Object.entries(obj||{}).map(([k,v])=>[keyMap[k]||k,v]));
const getOff = d => expandKeys(d?.o, OFF_KEY_MAP);
const getDef = d => expandKeys(d?.d, DEF_KEY_MAP);
const getRawOff = d => expandKeys(d?.ro, OFF_KEY_MAP);
const getRawDef = d => expandKeys(d?.rd, DEF_KEY_MAP);

