                      <div style={{ fontSize: 10, fontWeight: 600, color: e?(e.fg>=0.50?"#059669":e.fg<=0.35?"#dc2626":"#374151"):"#d1d5db" }}>{e?`${Math.round(e.fg*100)}%`:"—"}</div>
