              if (!prof) return null;
              const zc = { RA:"#1a6ef5", Paint:"#60a5fa", MR:"#93c5fd", C3:"#fbbf24", AB3:"#f59e0b" };
              const zs = ZONE_ORDER.filter(z => prof.zones[z] && prof.zones[z].freq > 0.005);
              const tot = zs.reduce((s,z) => s + prof.zones[z].freq, 0) || 1;
